#define NFUNCS 427
static char skip[NFUNCS];
static int fi = 0, ci = 0, calls = 0, done = 0, perFunction = 12;
static SDFile* progress;
static uint32_t hash(const char* s) { uint32_t h = 5381; while (*s) h = h * 33 + (uint8_t)*s++; return h; }
static void logLine(SDFile* f, const char* a, const char* b) {
    pd->file->write(f, a, (unsigned)strlen(a)); if (b) pd->file->write(f, b, (unsigned)strlen(b)); pd->file->write(f, "\n", 1); pd->file->flush(f);
}
static int update(void* ud) {
    if (done) return 0;
    for (int k = 0; k < 40; k++) {
        while (fi < NFUNCS && skip[fi]) fi++;
        if (fi >= NFUNCS) {
            done = 1;
            char* msg; pd->system->formatString(&msg, "done calls %d", calls);
            SDFile* f = pd->file->open("result.txt", kFileWrite); logLine(f, msg, NULL); pd->file->close(f);
            return 0;
        }
        if (ci == 0) rng = hash(*table[fi].name) ^ 0x9E3779B9u;
        char num[16]; int c = ci, l = 0; char tmp[16]; do { tmp[l++] = (char)('0' + c % 10); c /= 10; } while (c); int j = 0; num[j++] = ' '; num[j++] = '#'; while (l) num[j++] = tmp[--l]; num[j] = 0;
        logLine(progress, *table[fi].name, num);
        pd->graphics->setDrawOffset(0, 0); pd->graphics->clearClipRect();
        table[fi].fn();
        calls++;
        if (++ci >= perFunction) { ci = 0; fi++; }
    }
    return 1;
}
int eventHandler(PlaydateAPI* p, PDSystemEvent event, uint32_t arg) {
    if (event == kEventInit) {
        pd = p;
        for (int i = 0; i < POOL; i++) {
            pools[T_LCDBitmap][i] = pd->graphics->newBitmap(8 + i * 7, 5 + i * 3, i % 2 ? kColorWhite : kColorBlack);
            pools[T_LCDBitmapTable][i] = pd->graphics->newBitmapTable(3, 8, 8);
            pools[T_LCDSprite][i] = pd->sprite->newSprite();
            pools[T_LCDTileMap][i] = pd->graphics->tilemap ? pd->graphics->tilemap->newTilemap() : NULL;
            pools[T_AudioSample][i] = pd->sound->sample->newSampleBuffer(1000 + i);
            pools[T_SamplePlayer][i] = pd->sound->sampleplayer->newPlayer();
            pools[T_FilePlayer][i] = pd->sound->fileplayer->newPlayer();
            pools[T_PDSynth][i] = pd->sound->synth->newSynth();
            pools[T_PDSynthLFO][i] = pd->sound->lfo->newLFO((LFOType)(i % 6));
            pools[T_PDSynthEnvelope][i] = pd->sound->envelope->newEnvelope(0.1f, 0.1f, 0.5f, 0.2f);
            pools[T_PDSynthSignalValue][i] = i % 2 ? pools[T_PDSynthLFO][i] : pools[T_PDSynthEnvelope][i];
            pools[T_ControlSignal][i] = pd->sound->controlsignal->newSignal();
            pools[T_SequenceTrack][i] = pd->sound->track->newTrack();
            pools[T_SoundSequence][i] = pd->sound->sequence->newSequence();
            pools[T_PDSynthInstrument][i] = pd->sound->instrument->newInstrument();
            pools[T_SoundChannel][i] = pd->sound->channel->newChannel();
            pools[T_TwoPoleFilter][i] = pd->sound->effect->twopolefilter->newFilter();
            pools[T_OnePoleFilter][i] = pd->sound->effect->onepolefilter->newFilter();
            pools[T_BitCrusher][i] = pd->sound->effect->bitcrusher->newBitCrusher();
            pools[T_RingModulator][i] = pd->sound->effect->ringmodulator->newRingmod();
            pools[T_DelayLine][i] = pd->sound->effect->delayline->newDelayLine(1000, 0);
            pools[T_Overdrive][i] = pd->sound->effect->overdrive->newOverdrive();
            pools[T_SoundEffect][i] = pools[T_BitCrusher][i];
            pools[T_SoundSource][i] = i % 2 ? pools[T_PDSynth][i] : pools[T_SamplePlayer][i];
            pools[T_SDFile][i] = pd->file->open(i % 2 ? "fuzzw.txt" : "fuzzr.txt", i % 2 ? kFileWrite : kFileAppend);
        }
        const char* err;
        pools[T_LCDFont][0] = pd->graphics->loadFont("/System/Fonts/Asheville-Sans-14-Bold.pft", &err);
        SDFile* s = pd->file->open("skip.txt", kFileReadData);
        if (s) {
            static char buf[16384]; int len = pd->file->read(s, buf, sizeof buf - 1); pd->file->close(s);
            if (len > 0) { buf[len] = 0; char* line = buf;
                while (*line) { char* e = line; while (*e && *e != '\n') e++; char c = *e; *e = 0;
                    for (int i = 0; i < NFUNCS; i++) if (!strcmp(*table[i].name, line)) skip[i] = 1;
                    if (!c) break; line = e + 1; } }
        }
        SDFile* cfg = pd->file->open("config.txt", kFileReadData);
        if (cfg) { char b[32] = { 0 }; pd->file->read(cfg, b, 31); pd->file->close(cfg); int v = 0; for (char* q = b; *q >= '0' && *q <= '9'; q++) v = v * 10 + *q - '0'; if (v > 0) perFunction = v; }
        progress = pd->file->open("progress.txt", kFileWrite);
        pd->system->setUpdateCallback(update, NULL);
    }
    return 0;
}
